import json, os, random, shutil, subprocess, sys

OLD = "/tmp/relay_old.py"
NEW = "/home/c/brix2/b/task050/relay.py"
ROOT = "/tmp/dt"

TOPO = {"nodes": ["n0", "n1"], "links": []}

def pol(rng):
    return [rng.randrange(0, 9) for _ in range(6)]

def canonical(obj):
    return (json.dumps(obj, ensure_ascii=False, separators=(",", ":"))
            + "\n").encode("utf-8")

def make_pack(h, path):
    pack = {"v": h[-1][0], "t": h[-1][1], "p": h[-1][2], "h": h}
    with open(path, "wb") as f:
        f.write(canonical(pack))

def build_walk(rng, h0, base, n_items, nseg):
    # Commits only ever append at the tip (n == len(H)); below the tip
    # an item is either a no-op or a commit matching an already-known
    # future version.
    H = [list(x) for x in h0]
    o = base
    items = []
    stalls = 0
    while len(items) < n_items:
        if o < len(H) - 1:
            r = rng.randrange(0, o + 1)
            if H[r][1] == H[o][1] and H[r][2] == H[o][2]:
                items.append([0, r, o, o, False]); stalls += 1
            elif H[r][1] == H[o + 1][1] and H[r][2] == H[o + 1][2]:
                if rng.random() < 0.4:
                    items.append([0, r, o, o + 1, False])
                items.append([0, r, o, o + 1, True]); o += 1
            else:
                items.append([0, r, o, o, False]); stalls += 1
        else:
            cand = [r for r in range(o + 1)
                    if H[r][1] != H[o][1] or H[r][2] != H[o][2]]
            if not cand:
                break
            r = rng.choice(cand)
            n = o + 1
            if rng.random() < 0.3:
                items.append([0, r, o, n, False])
                if len(items) >= n_items:
                    break
            items.append([0, r, o, n, True])
            H.append([n, H[r][1], H[r][2]]); o = n
        if stalls > 2 * n_items + 5:
            break
    e = 0
    for it in items:
        e += rng.randrange(0, 3)
        it[0] = e
    cuts = sorted(rng.sample(range(1, len(items)),
                             min(nseg - 1, len(items) - 1)))
    bounds = [0] + cuts + [len(items)]
    segs, o = [], base
    for lo, hi in zip(bounds[:-1], bounds[1:]):
        chunk = items[lo:hi]
        c = chunk[-1][3] if chunk[-1][4] else chunk[-1][2]
        segs.append([o, chunk, c]); o = c
    return H, segs

def snapshot(d):
    out = {}
    for name in os.listdir(d):
        p = os.path.join(d, name)
        if os.path.isfile(p) and ".tmp." not in name:
            with open(p, "rb") as f:
                out[name] = f.read()
    return out

def run_one(script, d, op):
    proc = subprocess.run([sys.executable, script, "config",
                           os.path.join(d, "PACK"), json.dumps(op)],
                          cwd=d, capture_output=True)
    return proc.returncode, proc.stdout, proc.stderr

CASES = 0

def case(label, setup, op):
    global CASES
    CASES += 1
    for tag, script in (("old", OLD), ("new", NEW)):
        d = os.path.join(ROOT, tag)
        shutil.rmtree(d, ignore_errors=True)
        os.makedirs(d)
        setup(d, script)
    so, sn = snapshot(os.path.join(ROOT, "old")), snapshot(os.path.join(ROOT, "new"))
    assert so == sn, (label, "setup mismatch", set(so) ^ set(sn))
    ro = run_one(OLD, os.path.join(ROOT, "old"), op)
    rn = run_one(NEW, os.path.join(ROOT, "new"), op)
    if ro != rn:
        print("RESULT MISMATCH", label)
        print("op:", json.dumps(op))
        print("old:", ro[0], ro[1][:600], ro[2][:200])
        print("new:", rn[0], rn[1][:600], rn[2][:200])
        sys.exit(1)
    fo, fn = snapshot(os.path.join(ROOT, "old")), snapshot(os.path.join(ROOT, "new"))
    if fo != fn:
        print("FILE MISMATCH", label)
        print("op:", json.dumps(op))
        for k in sorted(set(fo) | set(fn)):
            if fo.get(k) != fn.get(k):
                print(" file", k)
                print("  old:", fo.get(k, b"")[:400])
                print("  new:", fn.get(k, b"")[:400])
        sys.exit(1)
    return ro

def replay_compare(label, op):
    ro = run_one(OLD, os.path.join(ROOT, "old"), op)
    rn = run_one(NEW, os.path.join(ROOT, "new"), op)
    if ro != rn or snapshot(os.path.join(ROOT, "old")) != snapshot(os.path.join(ROOT, "new")):
        print("REPLAY MISMATCH", label, ro, rn)
        sys.exit(1)
    return ro

def mutate(rng, segs):
    segs = json.loads(json.dumps(segs))
    kind = rng.randrange(10)
    si = rng.randrange(len(segs))
    b, L, c = segs[si]
    ii = rng.randrange(len(L))
    it = L[ii]
    if kind == 0:
        segs[si][0] = b + 1
    elif kind == 1:
        segs[si][2] = c + 1
    elif kind == 2:
        it[0] = it[0] - 10
    elif kind == 3:
        it[2] = it[2] + 1
    elif kind == 4:
        it[1] = it[2] + 1
    elif kind == 5:
        if it[4]:
            it[4] = False; it[3] = it[2]
        else:
            it[4] = True
    elif kind == 6:
        it[3] = it[2] + 2 if not it[4] else it[3] + 1
    elif kind == 7:
        segs[si][2] = L[-1][2] if L[-1][4] else L[-1][3]
    elif kind == 8:
        if ii + 1 < len(L):
            L[ii + 1][2] += 1
    else:
        if si + 1 < len(segs):
            segs[si + 1][0] += 1
    return segs

def gen_checkpoint(kind, base, segs, Hf, I=None):
    out = {}
    for tag, script in (("old", OLD), ("new", NEW)):
        tmp = os.path.join(ROOT, "gen_" + tag)
        shutil.rmtree(tmp, ignore_errors=True)
        os.makedirs(tmp)
        make_pack(Hf, os.path.join(tmp, "PACK"))
        genop = [12, 0, base, segs, I, "C"] if kind == 12 \
            else [13, 0, base, segs, "C"]
        rr = run_one(script, tmp, genop)
        if rr[0] != 0:
            print("GEN FAIL", tag, kind, rr[0], rr[2])
            print("base", base, "I", I)
            print("Hf", json.dumps(Hf))
            print("segs", json.dumps(segs))
            sys.exit(2)
        out[tag] = open(os.path.join(tmp, "C"), "rb").read()
    assert out["old"] == out["new"], "checkpoint bytes differ"
    return out["new"]

def prime(d, script, base, pre_segs, h_start):
    make_pack(h_start, os.path.join(d, "PACK"))
    if pre_segs:
        rr = run_one(script, d, [11, 1, base, pre_segs, None])
        assert rr[0] == 0, ("prime failed", rr[0], rr[2])

def write_C_variant(d, cbytes, pick):
    p = os.path.join(d, "C")
    if pick < 0.55:
        open(p, "wb").write(cbytes)
    elif pick < 0.75:
        open(p, "wb").write(b"{bad json")
    elif pick < 0.9:
        bad = json.loads(cbytes)
        if isinstance(bad.get("points"), list):
            bad["b"] = bad["b"] + 1
        else:
            bad["d"] = "0" * 64
        open(p, "wb").write(canonical(bad))
    # else missing

def main():
    rng = random.Random(20260926)
    shutil.rmtree(ROOT, ignore_errors=True)
    os.makedirs(ROOT)
    for it in range(500):
        v0 = rng.randrange(0, 8)
        base = rng.randrange(0, v0 + 1)
        pool = [pol(rng) for _ in range(rng.randrange(2, 5))]
        h0 = [[i, TOPO, pool[rng.randrange(len(pool))]]
              for i in range(v0 + 1)]
        n_items = rng.randrange(1, 16)
        nseg = rng.randrange(1, min(4, n_items) + 1)
        Hf, segs = build_walk(rng, h0, base, n_items, nseg)
        if len(segs) < 1 or any(not s[1] for s in segs):
            continue
        choice = rng.randrange(3)
        outname = rng.choice(["OUT", "ck.json"])

        if choice == 0:  # op11
            m = rng.randrange(0, 2)
            pre_out = rng.random() < 0.5
            out_kind = rng.random()
            def setup(d, script, m=m, pre_out=pre_out, out_kind=out_kind):
                make_pack(Hf if m == 0 else h0, os.path.join(d, "PACK"))
                if m == 0 and pre_out:
                    p = os.path.join(d, outname)
                    if out_kind < 0.5:
                        open(p, "wb").write(canonical(segs))
                    else:
                        open(p, "wb").write(b"junk\n")
            use_segs = mutate(rng, segs) if rng.random() < 0.35 else segs
            op = [11, m, base, use_segs, outname if m == 0 else None]
            r = case(f"op11 it{it} m{m}", setup, op)
            if m == 1 and r[0] == 0:
                replay_compare(f"op11-replay it{it}",
                               [11, 1, base, use_segs, None])

        elif choice == 1:  # op12
            I = rng.randrange(0, len(segs) + 1)
            m = rng.randrange(0, 2)
            cbytes = gen_checkpoint(12, base, segs, Hf, I) if m == 1 else None
            def setup(d, script, m=m, cbytes=cbytes):
                if m == 0:
                    make_pack(Hf, os.path.join(d, "PACK"))
                else:
                    prime(d, script, base, segs[:I], h0)
                    write_C_variant(d, cbytes, rng.random())
            use_segs = mutate(rng, segs) if rng.random() < 0.3 else segs
            op = [12, m, base, use_segs, I, "C"]
            r = case(f"op12 it{it} m{m} I{I}", setup, op)
            if m == 1 and r[0] == 0:
                replay_compare(f"op12-replay it{it}",
                               [12, 1, base, use_segs, I, "C"])

        else:  # op13
            m = rng.randrange(0, 2)
            cbytes = gen_checkpoint(13, base, segs, Hf) if m == 1 else None
            k = rng.randrange(0, len(segs) + 1)
            def setup(d, script, m=m, cbytes=cbytes, k=k):
                if m == 0:
                    make_pack(Hf, os.path.join(d, "PACK"))
                else:
                    prime(d, script, base, segs[:k], h0)
                    write_C_variant(d, cbytes, rng.random())
            use_segs = mutate(rng, segs) if rng.random() < 0.3 else segs
            op = [13, m, base, use_segs, "C"]
            r = case(f"op13 it{it} m{m} k{k}", setup, op)
            if m == 1 and r[0] == 0:
                replay_compare(f"op13-replay it{it}",
                               [13, 1, base, use_segs, "C"])

        if it % 50 == 0:
            print("iter", it, "cases", CASES)
    print("ALL OK", CASES, "cases")

main()

